import React, { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "./ViewInfo.css";

export default function ViewInfo() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  // Property data
  const propertyData = {
    1: {
      title: "Isidro Boarding House",
      location: "Brgy.Bakhaw Mandurriao Iloilo",
      price: 2500,
      images: ["room1.jpg", "room2.jpg", "room3.jpg", "room4.jpg", "room5.jpg" ],
      description: "A comfortable boarding house near the university",
      amenities: [
        "Free used of shared kitchen",
        "Laundry area available",
        "Clean shared bathrooms(regularly maintained)"
      ],
      highlights: ["1 Month Deposit", "Wifi", "Parking"],
      contact: {
        name: "Property Owner",
        phone: "09123456789",
        email: "contact@example.com"
      }
    },
    2: {
      title: "Maggs Boarding House",
      location: "Burgos St. La Paz",
      price: 2500,
      images: ["Mags bh.jpg", "bakhaw bh.jpg"],
      description: "A single room with double spacer bed",
      amenities: [
        "Free used of shared kitchen",
        "Laundry area available",
        "Clean shared bathrooms(regularly maintained)"
      ],
      highlights: ["1 Month Deposit", "Wifi", "Parking", "Air Condition"],
      contact: {
        name: "Jhean Kate Rizal",
        phone: "09299994538",
        email: "juan@gmail.com",
        facebook: "Jhean Kate fb.com"
      }
    },
    3: {
      title: "WIT area",
      location: "Pueblo Conception Mandurriao Iloilo",
      price: 2500,
      images: ["mandu bh 1.jpg"],
      description: "Convenient location near WIT",
      amenities: [
        "Free used of shared kitchen",
        "Laundry area available",
        "Clean shared bathrooms(regularly maintained)"
      ],
      highlights: ["1 Month Deposit", "Wifi"],
      contact: {
        name: "Property Owner",
        phone: "09123456789",
        email: "contact@example.com"
      }
    }
  };

  const property = propertyData[id];

  if (!property) {
    return (
      <div className="property-detail">
        <h2>Property not found</h2>
        <button onClick={() => navigate("/")}>Back to Home</button>
      </div>
    );
  }

  const nextImage = () => {
    setCurrentImageIndex((prev) => 
      prev === property.images.length - 1 ? 0 : prev + 1
    );
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => 
      prev === 0 ? property.images.length - 1 : prev - 1
    );
  };

  // 1. New handler for Rent button
  const handleRent = () => {
    // Navigate to rental page ('/rent') and pass the full property object as state.
    // The target component can access this via: useLocation().state.property
    navigate('/rent', { 
      state: { property }  
    });
  };

  return (
    <div className="property-detail">
      <div className="detail-content">
        <div className="detail-left">
          {/* Image Gallery */}
          <div className="image-gallery">
            <div className="main-image-container">
              {property.images.length > 1 && (
                <>
                  <button className="nav-arrow left" onClick={prevImage}>‹</button>
                  <button className="nav-arrow right" onClick={nextImage}>›</button>
                </>
              )}
              <img 
                src={property.images[currentImageIndex]} 
                alt={`${property.title} - ${currentImageIndex + 1}`}
                className="main-image"
              />
              {property.images.length > 1 && (
                <div className="image-counter">
                  {currentImageIndex + 1} / {property.images.length}
                </div>
              )}
            </div>

            {property.images.length > 1 && (
              <div className="thumbnail-container">
                {property.images.map((img, idx) => (
                  <img
                    key={idx}
                    src={img}
                    alt={`Thumbnail ${idx + 1}`}
                    className={`thumbnail ${idx === currentImageIndex ? 'active' : ''}`}
                    onClick={() => setCurrentImageIndex(idx)}
                  />
                ))}
              </div>
            )}
          </div>

          <h2 className="property-title">{property.title}</h2>
          <p className="property-location">{property.location}</p>
          <p className="property-price">₱ {property.price.toLocaleString()}/month</p>

          <div className="highlights-section">
            <h3>HIGHLIGHTS</h3>
            <div className="highlights-grid">
              {property.highlights.map((highlight, idx) => (
                <div key={idx} className="highlight-badge">
                  {highlight}
                </div>
              ))}
            </div>
          </div>

          <div className="details-section">
            <h3>DETAILS</h3>
            <p>{property.description}</p>

            <h4>Amenities</h4>
            <ul>
              {property.amenities.map((amenity, idx) => (
                <li key={idx}>✓ {amenity}</li>
              ))}
            </ul>

            <h4>Monthly Rate</h4>
            <ul>
              <li>✓ Starts at {property.price.toLocaleString()} php per person</li>
              <li>✓ Water and electricity bill are separated</li>
              <li>✓ 1 month advanced, 1 month deposits</li>
            </ul>
          </div>
        </div>

        <div className="detail-right">
          <div className="contact-card">
            <h3>Contact us</h3>
            <div className="contact-info">
              <input type="text" value={property.contact.name} readOnly />
              <input type="text" value={property.contact.phone} readOnly />
              <input type="text" value={property.contact.email} readOnly />
              {property.contact.facebook && (
                <input type="text" value={property.contact.facebook} readOnly />
              )}
            </div>
            <div className="update-info">
              <span>🕐</span>
              <span>The owner updated the listings about 4 hours ago</span>
            </div>
          </div>

          <div className="location-card">
            <h3>LOCATION</h3>
            <div className="map-placeholder">
              <p>{property.location}</p>
            </div>
          </div>

          {/* 2. Updated Rent button with onClick handler */}
          <button className="rent-button" onClick={handleRent}>
            Rent
          </button>
        </div>
      </div>
    </div>
  );
}
